import { chromium } from 'playwright';
import { createRequire } from 'node:module';
import { createInterface } from 'node:readline';
const require=createRequire(import.meta.url), {createGameServer}=require('../../scripts/lib/gameServer.cjs');
const server=createGameServer({root:process.cwd()+'/'});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
const browser=await chromium.launch({executablePath:'/workspace/scratch/3a00c06b9899/browser-bin/chromium',headless:true,args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist','--disable-background-timer-throttling']});
const context=await browser.newContext({viewport:{width:1280,height:800}});
let page=await context.newPage();
page.on('pageerror', e=>console.log(JSON.stringify({pageError:e.message})));
let failures=0;
page.on('response',r=>{if(r.status()>=400&&failures++<35)console.log(JSON.stringify({http:r.status(),url:r.url()}));});
page.on('console',m=>{if(m.type()==='error')console.log(JSON.stringify({console:m.text().slice(0,350)}));});
await page.goto(`http://127.0.0.1:${server.address().port}/`,{waitUntil:'domcontentloaded',timeout:90000});
await page.waitForFunction(()=>!!window.SF?.state,null,{timeout:120000});
await page.keyboard.press('Enter');
console.log(JSON.stringify({ready:true,rootHarnessPid:process.pid,url:page.url()}));
let pending=Promise.resolve();
const input=createInterface({input:process.stdin,crlfDelay:Infinity});
let closing=false; const cleanup=async()=>{if(closing)return;closing=true;try{await browser.close();}finally{server.close();process.exit(0);}};
input.on('close',()=>{void cleanup();});process.on('SIGTERM',()=>{void cleanup();});process.on('SIGINT',()=>{void cleanup();});
input.on('line', line=>{
  pending=pending.then(async()=>{
    try {
      const c=JSON.parse(line);let result;
      if(c.action==='status')result=await page.evaluate(()=>({mode:window.SF?.state?.mode,paused:window.SF?.state?.paused,text:document.body.innerText.slice(0,7000),player:window.SF?.state?.entities?.get(window.SF?.state?.playerId)?.pos}));
      else if(c.action==='click') { await page.getByRole('button',{name:c.name,exact:c.exact!==false}).click({timeout:15000});result='clicked'; }
      else if(c.action==='selector') { await page.locator(c.selector).click({timeout:15000});result='clicked'; }
      else if(c.action==='key') { await page.keyboard.press(c.key);result='key'; }
      else if(c.action==='fill') { await page.locator(c.selector).fill(c.value);result='filled'; }
      else if(c.action==='file') { await page.locator(c.selector).setInputFiles(c.path,{timeout:15000});result='file selected'; }
      else if(c.action==='pulse') { await page.keyboard.down(c.key);await page.waitForTimeout(Math.min(c.ms||100,5000));await page.keyboard.up(c.key);result='pulse'; }
      else if(c.action==='drag') { await page.mouse.move(c.x1,c.y1);await page.mouse.down();await page.mouse.move(c.x2,c.y2,{steps:20});await page.mouse.up();result='drag'; }
      else if(c.action==='double') { await page.mouse.dblclick(c.x,c.y);result='double'; }
      else if(c.action==='down') { await page.keyboard.down(c.key);result='down'; }
      else if(c.action==='up') { await page.keyboard.up(c.key);result='up'; }
      else if(c.action==='mouse') { await page.mouse.click(c.x,c.y,{button:c.button||'left'});result='mouse'; }
      else if(c.action==='move') { await page.mouse.move(c.x,c.y);result='move'; }
      else if(c.action==='wheel') { await page.mouse.wheel(c.x||0,c.y);result='wheel'; }
      else if(c.action==='shot') { await page.screenshot({path:c.path,timeout:45000});result=c.path; }
      else if(c.action==='read') { let timer; try { result=await Promise.race([page.evaluate(c.expression), new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Read-only observation exceeded 10 seconds')),10000);})]); } finally { clearTimeout(timer); } }
      else if(c.action==='recover') { const url=page.url(); page=await context.newPage(); await page.goto(url,{waitUntil:'domcontentloaded',timeout:90000}); result='reopened same context'; }
      else if(c.action==='reload') { await page.reload({waitUntil:'domcontentloaded'}); result='reloaded'; }
      else if(c.action==='quit') { await browser.close();server.close();process.exit(0); }
      else throw Error('Unknown action');
      console.log(JSON.stringify({done:c.action,result}));
    }catch(e){ console.log(JSON.stringify({error:e.message})); }
  });
});
